  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --primary: #1868DB;
      --primary-dark: #1255b5;
      --primary-light: #EBF2FF;
      --accent: #FF613D;
      --accent-dark: #e54e2a;
      --text-dark: #292A2E;
      --text-mid: #4B5563;
      --text-light: #9CA3AF;
      --bg-white: #FFFFFF;
      --bg-light: #F8F9FE;
      --bg-gray: #F3F4F6;
      --border: #E5E7EB;
      --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
      --shadow-md: 0 4px 20px rgba(0,0,0,.08);
      --shadow-lg: 0 20px 60px rgba(0,0,0,.12);
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
