    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', -apple-system, sans-serif; color: var(--text-dark); background: var(--bg-white); line-height: 1.6; -webkit-font-smoothing: antialiased; }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .container-wide { max-width: 1400px; margin: 0 auto; padding: 0 24px; }
    /* Buttons */
    .btn { display: inline-flex; align-items: center; gap: 8px; padding: 12px 24px; border-radius: var(--radius-sm); font-weight: 600; font-size: 15px; text-decoration: none; transition: all .2s ease; cursor: pointer; border: none; }
    .btn-primary { background: var(--primary); color: #fff; }
    .btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: 0 6px 20px rgba(24,104,219,.3); }
    .btn-accent { background: var(--accent); color: #fff; }
    .btn-accent:hover { background: var(--accent-dark); transform: translateY(-1px); }
    .btn-outline { border: 2px solid var(--border); background: transparent; color: var(--text-dark); }
    .btn-outline:hover { border-color: var(--primary); color: var(--primary); }
    .btn-ghost { background: transparent; color: var(--text-dark); font-weight: 500; padding: 10px 16px; }
    .btn-ghost:hover { color: var(--primary); }
    .btn-lg { padding: 16px 32px; font-size: 16px; border-radius: 10px; }
    /* Nav */
    .navbar { position: sticky; top: 0; z-index: 100; background: rgba(255,255,255,.95); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); }
    .nav-inner { display: flex; align-items: center; height: 68px; gap: 32px; }
    .logo { display: flex; align-items: center; gap: 8px; text-decoration: none; font-weight: 800; font-size: 20px; color: var(--text-dark); flex-shrink: 0; }
    .logo-icon { width: 32px; height: 32px; background: var(--primary); border-radius: 8px; display: flex; align-items: center; justify-content: center; }
    .logo-icon svg { width: 18px; height: 18px; fill: #fff; }
    .nav-links { display: flex; list-style: none; gap: 4px; flex: 1; }
    .nav-links a { text-decoration: none; color: var(--text-mid); font-weight: 500; font-size: 15px; padding: 8px 12px; border-radius: var(--radius-sm); transition: all .2s; }
    .nav-links a:hover { color: var(--primary); background: var(--primary-light); }
    .nav-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
    /* Hero */
    .hero { padding: 100px 0 80px; text-align: center; background: linear-gradient(180deg, var(--bg-light) 0%, var(--bg-white) 100%); position: relative; overflow: hidden; }
    .hero::before { content: ''; position: absolute; top: -200px; left: 50%; transform: translateX(-50%); width: 800px; height: 800px; background: radial-gradient(circle, rgba(24,104,219,.06) 0%, transparent 70%); pointer-events: none; }
    .hero-badge { display: inline-flex; align-items: center; gap: 6px; background: var(--primary-light); color: var(--primary); font-size: 13px; font-weight: 600; padding: 6px 14px; border-radius: 100px; margin-bottom: 24px; border: 1px solid rgba(24,104,219,.15); }
    .hero h1 { font-size: clamp(44px, 6vw, 80px); font-weight: 900; line-height: 1.05; letter-spacing: -2px; color: var(--text-dark); max-width: 800px; margin: 0 auto 24px; }
    .hero h1 span { color: var(--primary); }
    .hero-sub { font-size: 20px; color: var(--text-mid); max-width: 540px; margin: 0 auto 40px; line-height: 1.6; }
    .hero-ctas { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-bottom: 60px; }
    .hero-mockup { max-width: 900px; margin: 0 auto; background: var(--bg-white); border-radius: var(--radius-xl); box-shadow: var(--shadow-lg); border: 1px solid var(--border); overflow: hidden; }
    .hero-mockup-bar { background: var(--bg-gray); padding: 12px 16px; display: flex; align-items: center; gap: 8px; }
    .dot { width: 12px; height: 12px; border-radius: 50%; }
    .dot-r { background: #FF5F57; }
    .dot-y { background: #FEBC2E; }
    .dot-g { background: #28C840; }
    .hero-mockup-screen { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); padding: 40px; min-height: 360px; display: flex; align-items: center; justify-content: center; position: relative; }
    .video-placeholder { background: rgba(255,255,255,.05); border: 2px dashed rgba(255,255,255,.15); border-radius: var(--radius-lg); width: 100%; max-width: 600px; height: 240px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 16px; color: rgba(255,255,255,.7); }
    .play-btn { width: 64px; height: 64px; background: var(--primary); border-radius: 50%; display: flex; align-items: center; justify-content: center; }
    .play-btn svg { width: 24px; height: 24px; fill: white; margin-left: 4px; }
    .rec-badge { position: absolute; top: 20px; right: 20px; background: #ef4444; color: white; font-size: 12px; font-weight: 700; padding: 4px 10px; border-radius: 100px; display: flex; align-items: center; gap: 6px; }
    .rec-dot { width: 6px; height: 6px; background: white; border-radius: 50%; animation: pulse 1.5s infinite; }
    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .3; } }
    /* Logo bar */
    .logo-bar { padding: 48px 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
    .logo-bar-label { text-align: center; font-size: 13px; font-weight: 600; color: var(--text-light); text-transform: uppercase; letter-spacing: .08em; margin-bottom: 32px; }
    .logos-track { display: flex; align-items: center; justify-content: center; gap: 48px; flex-wrap: wrap; }
    .logo-item { font-size: 20px; font-weight: 800; color: var(--text-light); letter-spacing: -0.5px; opacity: .6; transition: opacity .2s; }
    .logo-item:hover { opacity: 1; }
    /* Section styles */
    section { padding: 96px 0; }
    .section-alt { background: var(--bg-light); }
    .section-dark { background: var(--text-dark); color: white; }
    .section-label { display: inline-flex; align-items: center; gap: 6px; background: var(--primary-light); color: var(--primary); font-size: 13px; font-weight: 700; padding: 6px 14px; border-radius: 100px; margin-bottom: 16px; }
    .section-label.new { background: #FEF3C7; color: #D97706; }
    .section-title { font-size: clamp(32px, 4vw, 52px); font-weight: 800; line-height: 1.15; letter-spacing: -1.5px; margin-bottom: 20px; }
    .section-sub { font-size: 18px; color: var(--text-mid); max-width: 560px; line-height: 1.7; }
    .text-center { text-align: center; }
    .text-center .section-sub { margin: 0 auto; }
    /* Feature highlight */
    .feature-highlight { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .feature-highlight.reverse { direction: rtl; }
    .feature-highlight.reverse > * { direction: ltr; }
    .feature-visual { background: linear-gradient(135deg, var(--primary-light) 0%, rgba(24,104,219,.03) 100%); border-radius: var(--radius-xl); padding: 40px; min-height: 360px; display: flex; align-items: center; justify-content: center; border: 1px solid rgba(24,104,219,.1); position: relative; overflow: hidden; }
    .feature-visual-inner { background: white; border-radius: var(--radius-lg); padding: 24px; box-shadow: var(--shadow-md); width: 100%; }
    .jira-mock { background: var(--bg-light); border-radius: var(--radius-sm); }
    .jira-header { background: var(--primary); color: white; padding: 10px 16px; border-radius: var(--radius-sm) var(--radius-sm) 0 0; font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 8px; }
    .jira-body { padding: 12px 16px; }
    .jira-row { display: flex; align-items: center; gap: 8px; padding: 6px 0; border-bottom: 1px solid var(--border); font-size: 12px; }
    .jira-row:last-child { border-bottom: none; }
    .jira-label { color: var(--text-light); min-width: 80px; }
    .jira-val { font-weight: 500; color: var(--text-dark); }
    .tag { display: inline-block; background: var(--primary-light); color: var(--primary); font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 4px; }
    /* Lists */
    .feature-list { list-style: none; margin: 24px 0; }
    .feature-list li { display: flex; align-items: flex-start; gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--border); }
    .feature-list li:last-child { border-bottom: none; }
    .check-icon { width: 20px; height: 20px; background: var(--primary); border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 2px; }
    .check-icon svg { width: 12px; height: 12px; fill: white; }
    .feature-list h4 { font-weight: 700; font-size: 15px; margin-bottom: 4px; }
    .feature-list p { font-size: 14px; color: var(--text-mid); }
    /* Security badges */
    .security-badges { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px; }
    .security-badge { display: flex; align-items: center; gap: 8px; background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.12); border-radius: var(--radius-sm); padding: 10px 16px; font-size: 13px; font-weight: 500; color: rgba(255,255,255,.85); }
    .security-badge svg { width: 16px; height: 16px; fill: #10B981; }
    /* Use cases */
    .use-cases-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; margin-top: 48px; }
    .use-case-card { background: var(--bg-white); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 32px; transition: all .2s; cursor: default; }
    .use-case-card:hover { box-shadow: var(--shadow-md); border-color: var(--primary); transform: translateY(-2px); }
    .use-case-icon { width: 48px; height: 48px; border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; margin-bottom: 16px; font-size: 24px; }
    .use-case-card h3 { font-size: 20px; font-weight: 700; margin-bottom: 8px; }
    .use-case-card p { color: var(--text-mid); font-size: 15px; }
    /* Features grid */
    .features-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 48px; }
    .feature-chip { background: var(--bg-white); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 20px 24px; display: flex; align-items: center; gap: 12px; font-weight: 600; font-size: 15px; transition: all .2s; }
    .feature-chip:hover { border-color: var(--primary); background: var(--primary-light); color: var(--primary); }
    .feature-chip svg { width: 20px; height: 20px; fill: var(--primary); flex-shrink: 0; }
    /* Integrations */
    .integrations-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; margin-top: 48px; }
    .int-card { background: var(--bg-white); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 20px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; font-size: 13px; font-weight: 600; color: var(--text-mid); transition: all .2s; min-height: 80px; }
    .int-card:hover { border-color: var(--primary); color: var(--primary); transform: translateY(-2px); box-shadow: var(--shadow-sm); }
    .int-icon { width: 32px; height: 32px; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 20px; }
    /* Blog */
    .blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; margin-top: 48px; }
    .blog-card { background: var(--bg-white); border: 1px solid var(--border); border-radius: var(--radius-lg); overflow: hidden; transition: all .2s; text-decoration: none; color: inherit; }
    .blog-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
    .blog-thumb { background: linear-gradient(135deg, var(--primary-light), rgba(255,97,61,.08)); height: 200px; display: flex; align-items: center; justify-content: center; font-size: 60px; }
    .blog-content { padding: 28px; }
    .blog-tag { font-size: 12px; font-weight: 700; color: var(--primary); text-transform: uppercase; letter-spacing: .06em; margin-bottom: 10px; }
    .blog-title { font-size: 18px; font-weight: 700; line-height: 1.4; margin-bottom: 12px; }
    .blog-excerpt { font-size: 14px; color: var(--text-mid); line-height: 1.65; }
    /* Testimonials */
    .testimonials-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }
    .testimonial-card { background: var(--bg-white); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 28px; display: flex; flex-direction: column; gap: 16px; }
    .stars { display: flex; gap: 2px; }
    .star { color: #F59E0B; font-size: 16px; }
    .testimonial-text { font-size: 15px; color: var(--text-mid); line-height: 1.7; flex: 1; font-style: italic; }
    .testimonial-author { display: flex; align-items: center; gap: 12px; }
    .author-avatar { width: 40px; height: 40px; border-radius: 50%; background: linear-gradient(135deg, var(--primary), var(--accent)); display: flex; align-items: center; justify-content: center; color: white; font-weight: 700; font-size: 14px; flex-shrink: 0; }
    .author-name { font-weight: 700; font-size: 14px; }
    .author-title { font-size: 13px; color: var(--text-light); }
    /* Enterprise CTA */
    .enterprise-cta-block { background: linear-gradient(135deg, var(--text-dark) 0%, #1a1f2e 100%); border-radius: var(--radius-xl); padding: 64px; display: flex; align-items: center; justify-content: space-between; gap: 40px; }
    .enterprise-cta-block h2 { font-size: 36px; font-weight: 800; color: white; letter-spacing: -1px; margin-bottom: 12px; }
    .enterprise-cta-block p { color: rgba(255,255,255,.7); font-size: 17px; }
    /* CTA Banner */
    .cta-banner { background: linear-gradient(135deg, var(--primary) 0%, #0d4faa 100%); padding: 80px 0; text-align: center; }
    .cta-banner h2 { font-size: 44px; font-weight: 900; color: white; letter-spacing: -1.5px; margin-bottom: 12px; }
    .cta-banner p { color: rgba(255,255,255,.8); font-size: 16px; margin-bottom: 32px; }
    .cta-banner .btn-primary { background: white; color: var(--primary); }
    .cta-banner .btn-primary:hover { background: var(--bg-light); }
    /* Footer */
    .footer { background: var(--text-dark); color: rgba(255,255,255,.7); padding: 72px 0 40px; }
    .footer-grid { display: grid; grid-template-columns: 2fr repeat(5, 1fr); gap: 40px; margin-bottom: 56px; }
    .footer-brand .logo { color: white; margin-bottom: 16px; display: flex; }
    .footer-brand p { font-size: 14px; line-height: 1.7; color: rgba(255,255,255,.5); margin-bottom: 20px; }
    .footer-col h4 { font-weight: 700; font-size: 13px; color: white; text-transform: uppercase; letter-spacing: .06em; margin-bottom: 16px; }
    .footer-col ul { list-style: none; }
    .footer-col ul li { margin-bottom: 10px; }
    .footer-col ul li a { text-decoration: none; color: rgba(255,255,255,.5); font-size: 14px; transition: color .2s; }
    .footer-col ul li a:hover { color: white; }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,.08); padding-top: 32px; display: flex; align-items: center; justify-content: space-between; font-size: 13px; color: rgba(255,255,255,.4); flex-wrap: wrap; gap: 12px; }
    .footer-bottom a { color: rgba(255,255,255,.4); text-decoration: none; }
    .footer-bottom a:hover { color: rgba(255,255,255,.7); }
    /* Cookie banner */
    #cookie-banner { position: fixed; bottom: 24px; left: 24px; right: 24px; max-width: 780px; margin: 0 auto; background: white; border-radius: var(--radius-lg); box-shadow: 0 20px 60px rgba(0,0,0,.18); border: 1px solid var(--border); padding: 28px 32px; z-index: 999; display: flex; gap: 24px; align-items: center; flex-wrap: wrap; }
    #cookie-banner p { flex: 1; font-size: 14px; color: var(--text-mid); min-width: 200px; }
    #cookie-banner p a { color: var(--primary); }
    .cookie-actions { display: flex; gap: 10px; flex-shrink: 0; flex-wrap: wrap; }
    .btn-cookie-accept { background: var(--primary); color: white; padding: 10px 20px; border-radius: var(--radius-sm); font-weight: 600; font-size: 14px; border: none; cursor: pointer; transition: background .2s; }
    .btn-cookie-accept:hover { background: var(--primary-dark); }
    .btn-cookie-reject { background: transparent; color: var(--text-mid); padding: 10px 20px; border-radius: var(--radius-sm); font-weight: 600; font-size: 14px; border: 1px solid var(--border); cursor: pointer; transition: all .2s; }
    .btn-cookie-reject:hover { border-color: var(--text-dark); color: var(--text-dark); }
    .btn-cookie-manage { background: transparent; color: var(--primary); padding: 10px 20px; font-weight: 600; font-size: 14px; border: none; cursor: pointer; text-decoration: underline; }
    /* Cookie modal */
    #cookie-modal { display: none; position: fixed; inset: 0; background: rgba(0,0,0,.5); z-index: 1000; align-items: center; justify-content: center; }
    #cookie-modal.open { display: flex; }
    .cookie-modal-inner { background: white; border-radius: var(--radius-xl); padding: 40px; max-width: 560px; width: 100%; margin: 24px; box-shadow: var(--shadow-lg); }
    .cookie-modal-inner h3 { font-size: 22px; font-weight: 800; margin-bottom: 8px; }
    .cookie-modal-inner > p { font-size: 14px; color: var(--text-mid); margin-bottom: 28px; line-height: 1.7; }
    .cookie-category { border: 1px solid var(--border); border-radius: var(--radius-md); padding: 20px; margin-bottom: 12px; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .cookie-category-info h4 { font-weight: 700; font-size: 15px; margin-bottom: 4px; }
    .cookie-category-info p { font-size: 13px; color: var(--text-mid); }
    .toggle-switch { position: relative; width: 44px; height: 24px; flex-shrink: 0; }
    .toggle-switch input { opacity: 0; width: 0; height: 0; }
    .toggle-track { position: absolute; inset: 0; background: var(--border); border-radius: 100px; cursor: pointer; transition: background .2s; }
    .toggle-track::before { content: ''; position: absolute; height: 18px; width: 18px; left: 3px; top: 3px; background: white; border-radius: 50%; transition: transform .2s; }
    .toggle-switch input:checked + .toggle-track { background: var(--primary); }
    .toggle-switch input:checked + .toggle-track::before { transform: translateX(20px); }
    .cookie-modal-actions { display: flex; gap: 10px; margin-top: 24px; justify-content: flex-end; }
    /* Responsive */
    @media (max-width: 1024px) {
      .features-grid { grid-template-columns: repeat(2, 1fr); }
      .integrations-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
      .feature-highlight { grid-template-columns: 1fr; gap: 40px; }
      .feature-highlight.reverse { direction: ltr; }
    }
    @media (max-width: 768px) {
      .nav-links { display: none; }
      .use-cases-grid { grid-template-columns: 1fr; }
      .testimonials-grid { grid-template-columns: 1fr; }
      .blog-grid { grid-template-columns: 1fr; }
      .enterprise-cta-block { flex-direction: column; text-align: center; padding: 40px 24px; }
      .hero-ctas { flex-direction: column; align-items: center; }
      .features-grid { grid-template-columns: 1fr 1fr; }
      .integrations-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      #cookie-banner { flex-direction: column; left: 12px; right: 12px; }
    }
  </style>
</head>
