<script>
  // Billing toggle
  const toggle = document.getElementById('billing-toggle-input');
  const labelMonthly = document.getElementById('label-monthly');
  const labelAnnual = document.getElementById('label-annual');
  const priceVals = document.querySelectorAll('.price-val');

  function updatePrices(isAnnual) {
    priceVals.forEach(el => {
      const monthly = parseInt(el.dataset.monthly);
      const annual = parseInt(el.dataset.annual);
      const val = isAnnual ? annual : monthly;
      el.textContent = val;
    });
    // Annual notes
    const notes = [
      { id: 'annual-note-starter', monthly: 0, annual: 0 },
      { id: 'annual-note-business', monthly: 18, annual: 15 },
      { id: 'annual-note-ai', monthly: 24, annual: 20 }
    ];
    notes.forEach(n => {
      const el = document.getElementById(n.id);
      if (!el) return;
      if (isAnnual && n.annual > 0) {
        const savings = Math.round((1 - n.annual / n.monthly) * 100);
        el.textContent = `Billed annually — Save ${savings}%`;
        el.style.color = '#059669';
      } else {
        el.textContent = '\u00a0';
      }
    });
    labelMonthly.classList.toggle('active', !isAnnual);
    labelAnnual.classList.toggle('active', isAnnual);
  }

  toggle.addEventListener('change', () => updatePrices(toggle.checked));

  // Team size slider
  const slider = document.getElementById('team-slider');
  const sliderDisplay = document.getElementById('slider-display');

  function updateSlider() {
    const val = parseInt(slider.value);
    sliderDisplay.textContent = val >= 200 ? '200+ users' : val + (val === 1 ? ' user' : ' users');
    // Update slider gradient
    const pct = ((val - 1) / 199) * 100;
    slider.style.background = `linear-gradient(to right, var(--primary) 0%, var(--primary) ${pct}%, var(--border) ${pct}%)`;
  }
  slider.addEventListener('input', updateSlider);
  updateSlider();

  // FAQ accordion
  function toggleFaq(btn) {
    const item = btn.closest('.faq-item');
    const isOpen = item.classList.contains('open');
    // Close all
    document.querySelectorAll('.faq-item.open').forEach(el => el.classList.remove('open'));
    if (!isOpen) item.classList.add('open');
  }

  // Plan extra features toggle
  function toggleExtra(plan, btn) {
    const extraEl = document.getElementById('extra-' + plan);
    const isOpen = extraEl.classList.contains('open');
    if (isOpen) {
      extraEl.classList.remove('open');
      btn.innerHTML = 'See all features <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M8.59 16.59L13.17 12 8.59 7.41 10 6l6 6-6 6z"/></svg>';
    } else {
      extraEl.classList.add('open');
      btn.innerHTML = 'Hide <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor" style="transform:rotate(90deg)"><path d="M8.59 16.59L13.17 12 8.59 7.41 10 6l6 6-6 6z"/></svg>';
    }
  }
</script>
